import type { ComponentProps } from '@solidjs/web'
import {
  Tooltip as UiTooltip,
  TooltipArrow as UiTooltipArrow,
  TooltipContent as UiTooltipContent,
  TooltipShortcut as UiTooltipShortcut,
  TooltipTrigger as UiTooltipTrigger,
} from '@ui-sdk/solid/tooltip'
import { createContext, omit, useContext } from 'solid-js'

import './tooltip.css'

/**
 * Tooltip, a 1:1 port of opencode's Tooltip (`@opencode/ui`, MIT):
 * `packages/ui/src/overlays/tooltip` (`tooltip-v2`), on top of ui-sdk's
 * headless Tooltip.
 *
 * Styling lives in `tooltip.css` as attribute rules (`data-appearance`,
 * `data-closed`, `data-side`, `data-motion`), so the compact look, the 120ms
 * in, the 80ms out and the large appearance match upstream. Behaviour (hover
 * and focus open, delay, grouping, dismissal, positioning, ARIA wiring) comes
 * from `@ui-sdk/solid`.
 *
 * Upstream's `standard` appearance reads opencode app-level tokens this repo
 * does not ship (`--surface-float-base`, `--text-invert-strong`, `--shadow-md`),
 * so only `compact`, upstream's default, and `large` are ported.
 *
 * `forceOpen` is upstream's prop: it maps to a controlled `open`, which keeps
 * the tooltip open and leaves `data-closed` off. `inactive` is not ported;
 * render the trigger without a Tooltip instead, or use ui-sdk's `disabled` to
 * keep the trigger but never open the tip. `contentClass`, `contentStyle` and
 * `triggerTabIndex` are not ported: `class`, `style` and the trigger's own
 * attributes already cover them.
 */

export type TooltipAppearance = 'compact' | 'large'

const TooltipAppearanceContext = createContext<TooltipAppearance>()

type UiTooltipProps = ComponentProps<typeof UiTooltip>

export type TooltipProps = Omit<UiTooltipProps, 'class' | 'render'> & {
  /** Defaults to `compact`, upstream's default. */
  appearance?: TooltipAppearance
  /** Holds the tooltip open, like upstream's `forceOpen`. */
  forceOpen?: boolean
}

export function Tooltip(props: TooltipProps) {
  const rest = omit(props, 'appearance', 'forceOpen')

  return (
    <TooltipAppearanceContext value={props.appearance ?? 'compact'}>
      <UiTooltip {...rest} open={props.forceOpen ? true : props.open} />
    </TooltipAppearanceContext>
  )
}

type UiTooltipTriggerProps = ComponentProps<typeof UiTooltipTrigger>

export type TooltipTriggerProps = Omit<
  UiTooltipTriggerProps,
  'class' | 'render'
> & {
  class?: UiTooltipTriggerProps['class']
  render?: UiTooltipTriggerProps['render']
}

export function TooltipTrigger(props: TooltipTriggerProps) {
  const rest = omit(props, 'class', 'render')

  return <UiTooltipTrigger {...rest} class={props.class} render={props.render} />
}

type UiTooltipContentProps = ComponentProps<typeof UiTooltipContent>

export type TooltipContentProps = Omit<
  UiTooltipContentProps,
  'class' | 'render'
> & {
  class?: UiTooltipContentProps['class']
  render?: UiTooltipContentProps['render']
}

export function TooltipContent(props: TooltipContentProps) {
  const appearance = useContext(TooltipAppearanceContext) ?? 'compact'
  const rest = omit(props, 'class', 'render')

  return (
    <UiTooltipContent
      {...rest}
      class={props.class}
      render={props.render}
      data-appearance={appearance}
    />
  )
}

type UiTooltipArrowProps = ComponentProps<typeof UiTooltipArrow>

export type TooltipArrowProps = Omit<UiTooltipArrowProps, 'class' | 'render'> & {
  class?: UiTooltipArrowProps['class']
  render?: UiTooltipArrowProps['render']
}

export function TooltipArrow(props: TooltipArrowProps) {
  const rest = omit(props, 'class', 'render')

  return <UiTooltipArrow {...rest} class={props.class} render={props.render} />
}

type UiTooltipShortcutProps = ComponentProps<typeof UiTooltipShortcut>

export type TooltipShortcutProps = Omit<
  UiTooltipShortcutProps,
  'class' | 'render'
> & {
  class?: UiTooltipShortcutProps['class']
  render?: UiTooltipShortcutProps['render']
}

export function TooltipShortcut(props: TooltipShortcutProps) {
  const rest = omit(props, 'class', 'render')

  return (
    <UiTooltipShortcut {...rest} class={props.class} render={props.render} />
  )
}

/*
 * 1:1 port of opencode's Tooltip (`@opencode/ui`, MIT):
 * packages/ui/src/overlays/tooltip/tooltip.css.
 *
 * Only the selectors changed, to meet ui-sdk's markup. Every value is upstream,
 * so the compact look, the 120ms in, the 80ms out and the large appearance all
 * match `data-component="tooltip-v2"`:
 *
 *   [data-component="tooltip-v2-trigger"]  →  [data-slot="tooltip-trigger"]
 *   [data-component="tooltip-v2"]          →  [data-slot="tooltip-content"]
 *   [data-appearance="compact|large"]      →  same (forwarded from the root prop)
 *   [data-closed]                          →  same (ui-sdk's attribute; the out
 *                                              rule also matches
 *                                              [data-ending-style], which is
 *                                              the state ui-sdk waits on for
 *                                              an exit animation)
 *   [data-popper-positioner] z-index       →  the content's own z-index
 *   :root[data-motion="reduce"]            →  same, plus the OS preference
 *
 * ui-sdk renders the content in the top layer with no positioner element, so
 * the two `z-index: 1000` rules upstream splits between the positioner and the
 * content land on the content alone.
 *
 * `transform-origin` reads ui-sdk's `--transform-origin` instead of Kobalte's
 * `--kb-tooltip-content-transform-origin`.
 *
 * `appearance="standard"` is not ported: it reads opencode app-level tokens
 * this repo does not ship (--surface-float-base, --text-invert-strong,
 * --shadow-md). It is also the only rule that sets `max-width: 320px`, so no
 * max-width is carried over; compact and large both size to their text.
 * `data-force-open` only appeared in that block. Upstream tooltips have no
 * arrow part, so ui-sdk's TooltipArrow ships unstyled.
 *
 * The trigger rule covers a bare trigger. A trigger rendered as another part,
 * like a Kitsaas Button through `render`, keeps that part's `data-slot`, so the
 * button's own layout rules apply instead.
 *
 * tooltip.css has no [data-color-scheme="dark"] block: the --v2-* tokens flip
 * with the scheme.
 *
 * The rule set is attribute driven, so the React, Vue and web-component
 * bindings can reuse this file unchanged.
 */

@layer components {
  [data-slot="tooltip-trigger"] {
    display: flex;
  }

  [data-slot="tooltip-content"] {
    z-index: 1000;
    box-sizing: border-box;
    display: inline-flex;
    flex-direction: row;
    align-items: center;
    padding: 5px 6px;
    gap: 6px;

    background: var(--v2-background-bg-layer-01);
    box-shadow: var(--v2-elevation-floating);
    border-radius: 4px;

    font-style: normal;
    font-weight: 530;
    font-size: 11px;
    line-height: 12px;
    letter-spacing: 0.05px;
    color: var(--v2-text-text-base);
    font-variant-numeric: tabular-nums;
    font-variation-settings: "slnt" 0;

    user-select: none;
    pointer-events: none;

    animation: tooltipV2In 120ms ease-out;
    transform-origin: var(--transform-origin);
  }

  [data-slot="tooltip-content"]:is([data-closed], [data-ending-style]) {
    animation: tooltipV2Out 80ms ease-in forwards;
  }

  [data-slot="tooltip-content"][data-appearance="large"] {
    padding: 12px;
    font-size: 13px;
    line-height: var(--line-height-compact);
    letter-spacing: -0.04px;
  }

  @keyframes tooltipV2In {
    from {
      opacity: 0;
      transform: scale(0.96);
    }

    to {
      opacity: 1;
      transform: scale(1);
    }
  }

  @keyframes tooltipV2Out {
    from {
      opacity: 1;
      transform: scale(1);
    }

    to {
      opacity: 0;
      transform: scale(0.96);
    }
  }

  :root[data-motion="reduce"] [data-slot="tooltip-content"],
  :root[data-motion="reduce"] [data-slot="tooltip-content"][data-closed],
  :root[data-motion="reduce"] [data-slot="tooltip-content"][data-ending-style] {
    animation: none;
  }

  @media (prefers-reduced-motion: reduce) {
    [data-slot="tooltip-content"],
    [data-slot="tooltip-content"][data-closed],
    [data-slot="tooltip-content"][data-ending-style] {
      animation: none;
    }
  }
}
